head.script:
scwin.__isShowHeaderFooter = function() {
    var trs = WebSquare.wUnit.getJq("#grid1_body_tbody").find("tr").not(".w2grid_hidedRow");
    var numTdHF = WebSquare.wUnit.getJq(trs).find("td.w2grid_groupby_depth_0").length;
    var count = 0;
    trs.each(function() {
        WebSquare.wUnit.getJq(this).find('td').each(function() {
            if (WebSquare.wUnit.getJq(this).hasClass("w2grid_groupby_depth_0")) {
                count++;
            }
        });
    });
    return (trs.length == 9) && (count == numTdHF);
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 브라우저에서 확인한다.
    //3. Check in browser
    // verify step 3. Header 와 Footer 부분이 표현된다.
    //3. Header and Footer parts are represented.
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowHeaderFooter()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
